void i40e_dcbnl_set_all ( struct i40e_vsi * vsi ) { struct net_device * dev = vsi -> netdev ; struct i40e_pf * pf = i40e_netdev_to_pf ( dev ) ; struct i40e_dcbx_config * dcbxcfg ; struct i40e_hw * hw = & pf -> hw ; struct dcb_app sapp ; u8 prio , tc_map ; int i ; if ( ! ( pf -> flags & I40E_FLAG_DCB_ENABLED ) ) { return ; } dcbxcfg = & hw -> local_dcbx_config ; for ( i = 0 ; i < dcbxcfg -> numapps ; i ++ ) { prio = dcbxcfg -> app [ i ] . priority ; tc_map = BIT ( dcbxcfg -> etscfg . prioritytable [ prio ] ) ; if ( tc_map & vsi -> tc_config . enabled_tc ) { sapp . selector = dcbxcfg -> app [ i ] . selector ; sapp . protocol = dcbxcfg -> app [ i ] . protocolid ; sapp . priority = prio ; dcb_ieee_setapp ( dev , & sapp ) ; } } dcbnl_ieee_notify ( dev , RTM_SETDCB , DCB_CMD_IEEE_SET , 0 , 0 ) ; } 